const CACHE='borali-shell-v8';const SHELL=['/','/index.html','/style.css','/app.mjs','/core.mjs','/insights.mjs','/maps.mjs','/physiology.mjs','/sync-model.mjs','/cloud.mjs','/features.mjs','/password-recovery.mjs','/rhythm.mjs','/location.mjs','/step-analytics.mjs','/analytics-ui.mjs','/icon.svg','/icon-180.png','/icon-192.png','/icon-512.png','/manifest.webmanifest'];self.addEventListener('install',event=>{event.waitUntil(caches.open(CACHE).then(c=>c.addAll(SHELL)));});self.addEventListener('activate',event=>event.waitUntil(caches.keys().then(keys=>Promise.all(keys.filter(k=>k.startsWith('borali-shell-')&&k!==CACHE).map(k=>caches.delete(k)))).then(()=>self.clients.claim())));self.addEventListener('fetch',event=>{if(event.request.method!=='GET'||new URL(event.request.url).origin!==self.location.origin)return;const path=new URL(event.request.url).pathname;if(!SHELL.includes(path))return;event.respondWith(fetch(event.request).catch(()=>caches.match(event.request).then(r=>r||caches.match('/index.html'))));});
